from pathlib import Path
p=Path("index.html")
s=p.read_text(encoding="utf-8")
old="""  function positionSuggestions16233(){const input=document.getElementById('searchInput'),menu=document.getElementById('earthlineSearchSuggestions15970');if(!input||!menu)return;const r=input.getBoundingClientRect(),run=document.getElementById('runBtn'),rr=run&&run.getBoundingClientRect?run.getBoundingClientRect():null,top=Math.max(r.bottom,rr&&Number.isFinite(rr.bottom)?rr.bottom:r.bottom)+7;menu.style.setProperty('left',Math.round(r.left)+'px','important');menu.style.setProperty('right','auto','important');menu.style.setProperty('top',Math.round(top)+'px','important');menu.style.setProperty('width',Math.round(r.width)+'px','important')}"""
current="""  function positionSuggestions16233(){const input=document.getElementById('searchInput'),menu=document.getElementById('earthlineSearchSuggestions15970');if(!input||!menu)return;const r=input.getBoundingClientRect(),run=document.getElementById('runBtn'),rr=run&&run.getBoundingClientRect?run.getBoundingClientRect():null,vh=Math.max(1,Number(window.innerHeight||document.documentElement.clientHeight||0)),vw=Math.max(1,Number(window.innerWidth||document.documentElement.clientWidth||0)),belowTop=Math.max(r.bottom,rr&&Number.isFinite(rr.bottom)?rr.bottom:r.bottom)+7,desired=Math.min(340,Math.max(96,Math.floor(vh*.58))),below=Math.max(0,vh-belowTop-8);let top,maxH;if(below>=96){top=belowTop;maxH=Math.min(desired,below)}else{const anchorTop=Math.min(r.top,rr&&Number.isFinite(rr.top)?rr.top:r.top)-7;maxH=Math.min(desired,Math.max(72,anchorTop-8));top=Math.max(8,anchorTop-maxH)}const width=Math.max(120,Math.min(r.width,vw-16)),left=Math.max(8,Math.min(r.left,vw-width-8));menu.style.setProperty('left',Math.round(left)+'px','important');menu.style.setProperty('right','auto','important');menu.style.setProperty('top',Math.round(top)+'px','important');menu.style.setProperty('width',Math.round(width)+'px','important');menu.style.setProperty('max-height',Math.round(maxH)+'px','important')}"""
new="""  function positionSuggestions16233(){const input=document.getElementById('searchInput'),menu=document.getElementById('earthlineSearchSuggestions15970');if(!input||!menu)return;const r=input.getBoundingClientRect(),run=document.getElementById('runBtn'),rr=run&&run.getBoundingClientRect?run.getBoundingClientRect():null,vh=Math.max(1,Number(window.innerHeight||document.documentElement.clientHeight||0)),vw=Math.max(1,Number(window.innerWidth||document.documentElement.clientWidth||0)),belowTop=Math.max(r.bottom,rr&&Number.isFinite(rr.bottom)?rr.bottom:r.bottom)+7,desired=Math.min(340,Math.max(96,Math.floor(vh*.58))),below=Math.max(0,vh-belowTop-8);let top,maxH;if(below>=96){top=belowTop;maxH=Math.min(desired,below)}else{const anchorTop=Math.min(r.top,rr&&Number.isFinite(rr.top)?rr.top:r.top)-7;maxH=Math.min(desired,Math.max(72,anchorTop-8));top=Math.max(8,anchorTop-maxH)}const width=Math.max(120,Math.min(r.width,vw-16)),left=Math.max(8,Math.min(r.left,vw-width-8));menu.style.setProperty('position','fixed','important');menu.style.setProperty('left',Math.round(left)+'px','important');menu.style.setProperty('right','auto','important');menu.style.setProperty('top',Math.round(top)+'px','important');menu.style.setProperty('width',Math.round(width)+'px','important');menu.style.setProperty('max-height',Math.round(maxH)+'px','important')}"""
if current in s:
    s=s.replace(current,new,1)
elif old in s:
    s=s.replace(old,new,1)
elif "menu.style.setProperty('position','fixed','important')" not in s:
    raise SystemExit("suggestion position owner not found")
p.write_text(s,encoding="utf-8")
print("patched viewport-fixed suggestion placement")
